1625: async function triggerAgenticOrchestration() {
1626:   const promptElement = $('prompt');
1627:   const prompt = promptElement.value.trim();
1628:   if (prompt.length < 12 || state.agentsAvailable === false) return;
1629:   const sequence = ++state.orchestrationSequence;
1630:   const revision = state.textRevision;
1631:   const requestId = clientRequestId('orchestrate');
1632:   const cursorOffset = typeof promptElement.selectionStart === 'number'
1633:     ? promptElement.selectionStart
1634:     : promptElement.value.length;
1635:   state.inflight = true;
1636:   renderAgentRecommendations();
1637: 
1638:   try {
1639:     const res = await fetch('/api/devin/orchestrate', {
1640:       method: 'POST',
1641:       headers: { 'Content-Type': 'application/json' },
1642:       body: JSON.stringify({
1643:         text: prompt,
1644:         cursor_offset: cursorOffset,
1645:         accepted_ghost_texts: [...state.acceptedGhostTexts],
1646:         request_id: requestId,
1647:       }),
1648:     });
1649:     if (!res.ok) {
1650:       if ([401, 403, 429, 503].includes(res.status)) {
1651:         setAgentAvailability(false, 'KI-Agenten sind gerade nicht verfügbar. Der Canvas und die manuelle Auswahl funktionieren weiter.');
1652:       }
1653:       return;
1654:     }
1655:     const data = await res.json();
1656:     const responseId = String(data.request_id || requestId);
1657:     const stale = sequence !== state.orchestrationSequence
1658:       || revision !== state.textRevision
1659:       || $('prompt').value.trim() !== prompt
1660:       || state.seenRequestIds.has(responseId);
1661:     if (stale) return;
1662:     state.seenRequestIds.add(responseId);
1663:     state.lastAppliedRequestId = responseId;
1664:     mergeAgentRecommendations(normalizeAgentRecommendations(data), true);
1665:     setAgentAvailability(true);
1666:   } catch (_) {
1667:     if (sequence === state.orchestrationSequence) {
1668:       setAgentAvailability(false, 'KI-Agenten sind gerade nicht erreichbar. Der Canvas und die manuelle Auswahl funktionieren weiter.');
1669:     }
1670:   } finally {
1671:     if (sequence === state.orchestrationSequence) {
1672:       state.inflight = false;
1673:       renderAgentRecommendations();
1674:     }
1675:   }
1676: }
