  if (!videos.length) {
    $('compose-error').textContent = 'Für die Videoerstellung wird mindestens eine Videodatei benötigt.';
    $('compose-error').hidden = false;
    return;
  }
  clearTimeout(state.canvasSaveTimeout);
  if (state.canvasHydrated) await saveCanvas(++state.saveRevision);
  state.uploading = true;
  $('script-result').hidden = true;
  $('progress').hidden = false;
