        chunk_id = str(chunk.get("id", ""))
        variants: list[dict[str, Any]] = []
        for variant in chunk.get("variants", []):
            if not isinstance(variant, dict):
                continue
            variant_id = str(variant.get("id", ""))
            variants.append(
                {
