// Update the inline grey ghost text directly in the canvas (flowing displacement for mid-text rewrites)
function updateGhostOverlay(hideWhileTyping = false) {
  const prompt = $('prompt');
  const display = $('canvas-display');
  const text = prompt.value || '';
  let ghost = state.activeGhostText || '';

  // Do NOT show ghost text while actively typing, if empty, or while user has text highlighted/selected
  const hasRangeSelection = document.activeElement === prompt && prompt.selectionStart !== prompt.selectionEnd;
  if (hideWhileTyping || !ghost || !text.trim() || hasRangeSelection) {
    display.innerHTML = '';
    display.classList.remove('visible');
    prompt.classList.remove('has-ghost');
    return;
  }

  // Insert ghost text at caret if caret is in the middle of text, else append at end of text
  let insertPos = text.length;
  if (document.activeElement === prompt && typeof prompt.selectionStart === 'number' && prompt.selectionStart < text.length) {
    insertPos = prompt.selectionStart;
  }

  const before = text.slice(0, insertPos);
  const after = text.slice(insertPos);

  // De-duplicate leading word if ghost starts with user's last typed word
  const lastWordMatch = before.match(/(\S+)\s*$/);
  if (lastWordMatch) {
    const lastWord = lastWordMatch[1].toLowerCase();
    const ghostWords = ghost.trim().split(/\s+/);
    if (ghostWords.length > 1 && ghostWords[0].toLowerCase() === lastWord) {
      ghost = ghostWords.slice(1).join(' ');
    }
  }

  let prefixSpace = '';
  if (before && !before.endsWith(' ') && !before.endsWith('\n') && !ghost.startsWith(' ') && !ghost.startsWith('.') && !ghost.startsWith(',')) {
    prefixSpace = ' ';
  }

  const escapedBefore = escapeHtml(before);
  const escapedGhost = escapeHtml(prefixSpace + ghost);
  const escapedAfter = escapeHtml(after);

  display.innerHTML = `<span>${escapedBefore}</span><span class="ghost-text-grey">${escapedGhost}</span><span>${escapedAfter}</span>`;
  display.classList.add('visible');
  prompt.classList.add('has-ghost');
}

