            attached = dict(current.get("attached_videos", {}))
            attached.update(request.attached_videos)
            updated = build_canvas_metadata(
                title=title,
                text=text,
                beats=beats,
                attached_videos=attached,
            )
            _save_canvas(edit_dir, updated)
