async function selectVariant(chunkId, variantId) {
  try {
    const response = await fetch(`/api/chunks/${encodeURIComponent(chunkId)}/selection`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ variant_id: variantId }),
    });
    if (!response.ok) throw new Error('Die Auswahl konnte nicht gespeichert werden.');
    const data = await response.json().catch(() => ({}));
    const chunks = Array.isArray(data.chunks)
      ? data.chunks
      : state.chunks.map(chunk => chunk.id === chunkId ? { ...chunk, selected: variantId } : chunk);
    renderChunkReview(chunks, data.selection_complete ?? null);
  } catch (error) {
    $('compose-error').textContent = error.message;
    $('compose-error').hidden = false;
  }
}

async function applyRecommendations() {
  if ($('apply-recommendations').disabled) return;
  state.applyingRecommendations = true;
  renderChunkReview(state.chunks);
  try {
    const response = await fetch('/api/chunks/recommendations/apply', { method: 'POST' });
    if (!response.ok) {
      const payload = await response.json().catch(() => ({}));
      throw new Error(payload.detail || 'Die KI-Empfehlungen konnten nicht übernommen werden.');
    }
    const data = await response.json().catch(() => ({}));
    const chunks = Array.isArray(data.chunks)
      ? data.chunks
      : state.chunks.map(chunk => {
          const recommendation = validChunkRecommendation(chunk);
          return recommendation ? { ...chunk, selected: recommendation.variant_id } : chunk;
        });
    state.applyingRecommendations = false;
    renderChunkReview(chunks, data.selection_complete ?? null);
  } catch (error) {
    state.applyingRecommendations = false;
    renderChunkReview(state.chunks);
    $('compose-error').textContent = error.message;
    $('compose-error').hidden = false;
  }
}

async function finalizeVideo() {
  if ($('finalize').disabled) return;
  state.finalizing = true;
  renderChunkReview(state.chunks, true);
  try {
    const response = await fetch('/api/finalize', { method: 'POST' });
    if (!response.ok) {
      const payload = await response.json().catch(() => ({}));
      throw new Error(payload.detail || 'Das finale Video konnte nicht gestartet werden.');
    }
    state.uploading = true;
    $('chunk-review').hidden = true;
    $('progress').hidden = false;
    $('progress-copy').textContent = 'Deine Auswahl wird zusammengesetzt …';
    poll();
  } catch (error) {
    state.finalizing = false;
    renderChunkReview(state.chunks);
    $('compose-error').textContent = error.message;
    $('compose-error').hidden = false;
  }
}

