function renderBeats(beats = []) {
  $('beats').innerHTML = beats.map(b => `<span class="beat" data-status="${b.status}">${b.id}</span>`).join('');
}

function validChunkRecommendation(chunk) {
  const recommendation = chunk?.recommendation;
  if (!recommendation || !recommendation.variant_id) return null;
  const status = String(recommendation.status || 'ready').toLowerCase();
  if (['failed', 'error', 'unavailable', 'pending'].includes(status)) return null;
  const variant = (chunk.variants || []).find(item => item.id === recommendation.variant_id);
  return variant ? recommendation : null;
}

function chunkVideoUrl(chunkId, variant) {
  return variant.video_url || `/api/chunks/${encodeURIComponent(chunkId)}/variants/${encodeURIComponent(variant.id)}/video`;
}

function renderChunkReview(chunks = [], selectionComplete = null) {
  state.chunks = Array.isArray(chunks) ? chunks : [];
  const list = $('chunk-list');
  list.innerHTML = '';

  state.chunks.forEach((chunk, index) => {
    const section = document.createElement('article');
    section.className = 'chunk';
    section.dataset.chunkId = chunk.id;

    const head = document.createElement('div');
    head.className = 'chunk-head';
    const heading = document.createElement('div');
    const title = document.createElement('h3');
    title.className = 'chunk-title';
    title.textContent = chunk.beat || `Chunk ${index + 1}`;
    const order = document.createElement('span');
    order.className = 'chunk-order';
    order.textContent = `${String(index + 1).padStart(2, '0')} / ${String(state.chunks.length).padStart(2, '0')}`;
    heading.append(title, order);

    const recommendation = chunk.recommendation;
    const validRecommendation = validChunkRecommendation(chunk);
    const recommendationBox = document.createElement('div');
    recommendationBox.className = 'recommendation';
    recommendationBox.dataset.status = String(recommendation?.status || (recommendation ? 'ready' : 'missing')).toLowerCase();
    const badge = document.createElement('span');
    badge.className = 'recommendation-badge';
    if (validRecommendation) {
      const variant = (chunk.variants || []).find(item => item.id === validRecommendation.variant_id);
      badge.textContent = `KI empfiehlt ${variant?.label || validRecommendation.variant_id}`;
      recommendationBox.append(badge, document.createTextNode(validRecommendation.reason || 'Auf Basis von Schnitt, Timing und Overlay-Prüfung.'));
    } else if (recommendation) {
      badge.textContent = 'KI-Empfehlung nicht verfügbar';
      recommendationBox.append(badge, document.createTextNode(recommendation.reason || 'Bitte manuell vergleichen.'));
    } else if (state.recommendationsStatus === 'pending') {
      recommendationBox.dataset.status = 'pending';
      badge.textContent = 'KI prüft beide Varianten';
      recommendationBox.append(badge, document.createTextNode('Du kannst bereits manuell auswählen.'));
    } else {
      badge.textContent = 'Manuelle Auswahl';
      recommendationBox.append(badge, document.createTextNode('Für diesen Chunk liegt keine KI-Empfehlung vor.'));
    }
    head.append(heading, recommendationBox);
    section.append(head);

    const grid = document.createElement('div');
    grid.className = 'variant-grid';
    const variants = (chunk.variants || []).slice(0, 2);
    while (variants.length < 2) variants.push(null);
    variants.forEach((variant, variantIndex) => {
      const card = document.createElement('div');
      card.className = 'variant';
      const selected = Boolean(variant && chunk.selected === variant.id);
      const recommended = Boolean(variant && validRecommendation?.variant_id === variant.id);
      card.dataset.selected = String(selected);
      card.dataset.recommended = String(recommended);

      const video = document.createElement('video');
      video.controls = true;
      video.preload = 'metadata';
      video.playsInline = true;
      if (variant) {
        video.src = chunkVideoUrl(chunk.id, variant);
        video.setAttribute('aria-label', `${chunk.beat || `Chunk ${index + 1}`} – ${variant.label || `Variante ${variantIndex + 1}`}`);
      } else {
        video.className = 'unavailable';
        video.setAttribute('aria-label', 'Variante nicht verfügbar');
      }

      const meta = document.createElement('div');
      meta.className = 'variant-meta';
      const copy = document.createElement('div');
      copy.className = 'variant-copy';
      const name = document.createElement('span');
      name.className = 'variant-name';
      const defaultName = variantIndex === 0 ? 'Version A · Clean Cut' : 'Version B · Motion Cut';
      name.textContent = variant ? [variant.label, variant.name].filter(Boolean).join(' · ') || defaultName : `${defaultName} · nicht verfügbar`;
      const strategy = document.createElement('span');
      strategy.className = 'variant-strategy';
      strategy.textContent = variant?.strategy || (variantIndex === 0 ? 'Ohne Motion Graphic' : 'Mit einer Motion Graphic');
      copy.append(name, strategy);

      const select = document.createElement('button');
      select.type = 'button';
      select.className = 'variant-select';
      const variantStatus = String(variant?.status || 'ready').toLowerCase();
      select.disabled = !variant || ['failed', 'error', 'unavailable', 'pending'].includes(variantStatus);
      select.textContent = selected ? 'Ausgewählt' : 'Auswählen';
      if (variant) select.addEventListener('click', () => selectVariant(chunk.id, variant.id));
      meta.append(copy, select);
      card.append(video, meta);
      grid.append(card);
    });
    section.append(grid);
    list.append(section);
  });

  const selectedCount = state.chunks.filter(chunk => Boolean(chunk.selected)).length;
  const localComplete = state.chunks.length > 0 && selectedCount === state.chunks.length;
  const complete = localComplete && selectionComplete !== false;
  $('selection-status').textContent = complete
    ? `Alle ${state.chunks.length} Chunks sind ausgewählt.`
    : `${selectedCount} von ${state.chunks.length} Chunks ausgewählt.`;
  $('finalize').disabled = !complete || state.finalizing;
  const recommendationCount = state.chunks.filter(validChunkRecommendation).length;
  $('apply-recommendations').disabled = recommendationCount === 0 || state.applyingRecommendations;

